------------ import ------------
local KTool = CS.Engine.Lib.KTool
local Animator = CS.UnityEngine.Animator
---@type MaidCoffeeConstants
local MaidCoffeeConstants = import("Game.MaidCoffee.MaidCoffeeConstants")
------------ import ------------

------------ define ------------
local AnimationStop = "WashingMachine_stop"
local AnimationPlay = "WashingMachine_run"
------------ define ------------

--- from: Assets/BundleResources/Arts/Prefab_item/MaidCoffee_sun_twisting_machine.prefab
---@class MaidCoffeeCatDrawMachine
---@field Env                           	MaidCoffeeCatDrawMachine                
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field MaidCoffee_night_Gashapon_02  	UnityEngine.Transform                   
---@field MaidCoffee_night_Gashapon_01  	UnityEngine.Transform                   
---@field ball01                        	UnityEngine.Transform                   
---@field drop_ball                     	UnityEngine.Transform                   
---@field AnimatorMachine               	UnityEngine.Transform                   
local MaidCoffeeCatDrawMachine = Class('MaidCoffeeCatDrawMachine')

function MaidCoffeeCatDrawMachine:__init()
    self.animator = nil
    self.balls = {}
end

function MaidCoffeeCatDrawMachine:__delete()
    self.animator = nil
    self.balls = nil
end

function MaidCoffeeCatDrawMachine:Awake()
    ---@type UnityEngine.Animator
    self.animator = KTool.GetComponent(self.AnimatorMachine.gameObject, typeof(Animator))
    self:StopAnimation()
end

---StopAnimation
---停止抽卡动画
function MaidCoffeeCatDrawMachine:StopAnimation()
    self.animator:Play(Animator.StringToHash(AnimationStop))
    if #self.balls > 0 then
        for i, v in pairs(self.balls) do
            KTool.SafeDelete(v.gameObject, true)
        end
    end
    self.balls = {}
end

function MaidCoffeeCatDrawMachine:PlayAnimation()
    self.animator:Play(Animator.StringToHash(AnimationPlay))
end

---CreateBall
---建立小球节点
---@param cats CatEggDojo[] @ 是否是十个小球
function MaidCoffeeCatDrawMachine:CreateBall(cats)
    if #cats == 1 then
        ---@type CatEggDojo
        local dojo = cats[1]
        ---@type MaidCoffeeCatRollConfigVo
        local vo = CfUtils.GetCfVo(AutoIds.IdSetting4000, 'MaidCoffeeCatRollConfigVo', dojo.catId)
        local  prefabGo = self.MaidCoffee_night_Gashapon_01.gameObject
        if vo.quality == MaidCoffeeConstants.CatBallQuality.Theme  then
            prefabGo = self.MaidCoffee_night_Gashapon_02.gameObject
        end
        ---@type UnityEngine.GameObject
        local go = KTool.Instantiate(self.ball01.gameObject, prefabGo, false)
        go.transform.localPosition = Vector3.zero
        go.transform.localRotation = Quaternion.identity
        --go.transform.localScale = Vector3.one
        table.insert(self.balls, go)
    else
        ---十抽的逻辑
        for i, v in pairs(cats) do
            local gameObjectKey = "ball0" .. tostring(i)
            local parent = self.drop_ball.transform:Find(gameObjectKey)
            if parent then
                ---@type MaidCoffeeCatRollConfigVo
                local vo = CfUtils.GetCfVo(AutoIds.IdSetting4000, 'MaidCoffeeCatRollConfigVo', v.catId)
                local  prefabGo = self.MaidCoffee_night_Gashapon_01.gameObject
                if vo.quality == MaidCoffeeConstants.CatBallQuality.Theme  then
                    prefabGo = self.MaidCoffee_night_Gashapon_02.gameObject
                end
                ---@type UnityEngine.GameObject
                local go = KTool.Instantiate(parent.gameObject, prefabGo, false)
                go.transform.localPosition = Vector3.zero
                go.transform.localRotation = Quaternion.identity
                --go.transform.localScale = Vector3.one
                table.insert(self.balls, go)
            end
        end
    end
end

function MaidCoffeeCatDrawMachine:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return MaidCoffeeCatDrawMachine